#define SDA_PIN 21
#define SCL_PIN 22
#define INA226_ADDRESS 0x40

// 100A / 75mV external shunt
const float SHUNT_OHMS = 0.00075;

// INA226 shunt-voltage register:
// 2.5 uV per bit
const float INA226_SHUNT_LSB_V = 0.0000025;

// =====================================================
// SERVER / LED STATE
// =====================================================

WebServer server(80);

uint8_t currentR = 128;
uint8_t currentG = 0;
uint8_t currentB = 255;

uint8_t brightness = 150;
bool lightsOn = true;

// =====================================================
// INA226 REGISTER READ
// =====================================================

int16_t readINA226Register(uint8_t reg) {

  Wire.beginTransmission(INA226_ADDRESS);
  Wire.write(reg);

  if (Wire.endTransmission(false) != 0) {
    return 0;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (Wire.available() < 2) {
    return 0;
  }

  uint16_t value =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  return (int16_t)value;
}

// =====================================================
// SHUNT VOLTAGE
// =====================================================

float getShuntVoltage_mV() {

  // Register 0x01 = Shunt Voltage
  int16_t raw =
    readINA226Register(0x01);

  float volts =
    raw * INA226_SHUNT_LSB_V;

  return volts * 1000.0;
}

// =====================================================
// CURRENT
// =====================================================

float getCurrent_A() {

  float shuntVoltage_V =
    getShuntVoltage_mV() / 1000.0;

  return
    shuntVoltage_V /
    SHUNT_OHMS;
}

// =====================================================
// LED FUNCTIONS
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
